<?php

declare(strict_types=1);

namespace App\Models;

use App\Enums\DisputeStatus;
use App\Support\Ids\HasPrefixedId;
use App\Support\Money\Money;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Relations\BelongsTo;
use Illuminate\Database\Eloquent\Relations\HasMany;
use Illuminate\Database\Eloquent\Relations\HasOne;
use Illuminate\Database\Eloquent\Relations\MorphMany;
use Illuminate\Support\Carbon;

/* @properties-start (generated by dev:model-docs) */
/**
 * @property string $id
 * @property string $number
 * @property string $order_id
 * @property string $buyer_id
 * @property string $seller_id
 * @property string|null $mediator_id
 * @property string $reason
 * @property string $requested
 * @property int|null $requested_amount
 * @property string $currency
 * @property int $frozen_amount
 * @property string $description
 * @property DisputeStatus $status
 * @property string|null $decision
 * @property int|null $amount_to_buyer
 * @property string|null $policy_reference
 * @property string|null $previous_order_status
 * @property Carbon|null $respond_by
 * @property Carbon|null $decision_due_at
 * @property Carbon|null $resolved_at
 * @property Carbon|null $created_at
 * @property Carbon|null $updated_at
 */
/* @properties-end */
class Dispute extends Model
{
    use HasPrefixedId;

    protected static string $idPrefix = 'dsp';

    public const REASONS = [
        'not_as_described' => 'Item not as described',
        'not_received' => 'Item not received',
        'damaged' => 'Item arrived damaged',
        'counterfeit' => 'Item is counterfeit',
    ];

    public const REQUESTS = ['full_refund', 'partial_refund', 'return_and_refund', 'replacement'];

    public const DECISIONS = ['release_to_seller', 'partial_refund', 'full_refund_with_return', 'full_refund_no_return'];

    protected $fillable = [
        'number', 'order_id', 'buyer_id', 'seller_id', 'mediator_id', 'reason', 'requested', 'requested_amount',
        'currency', 'frozen_amount', 'description', 'status', 'decision', 'amount_to_buyer', 'policy_reference',
        'previous_order_status', 'respond_by', 'decision_due_at', 'resolved_at',
    ];

    protected function casts(): array
    {
        return [
            'status' => DisputeStatus::class,
            'requested_amount' => 'integer',
            'frozen_amount' => 'integer',
            'amount_to_buyer' => 'integer',
            'respond_by' => 'datetime',
            'decision_due_at' => 'datetime',
            'resolved_at' => 'datetime',
        ];
    }

    /** @return BelongsTo<Order, $this> */
    public function order(): BelongsTo
    {
        return $this->belongsTo(Order::class);
    }

    /** @return BelongsTo<User, $this> */
    public function buyer(): BelongsTo
    {
        return $this->belongsTo(User::class, 'buyer_id');
    }

    /** @return BelongsTo<User, $this> */
    public function seller(): BelongsTo
    {
        return $this->belongsTo(User::class, 'seller_id');
    }

    /** @return BelongsTo<User, $this> */
    public function mediator(): BelongsTo
    {
        return $this->belongsTo(User::class, 'mediator_id');
    }

    /** @return HasMany<DisputeMessage, $this> */
    public function messages(): HasMany
    {
        return $this->hasMany(DisputeMessage::class)->orderBy('created_at');
    }

    /** @return HasMany<DisputeProposal, $this> */
    public function proposals(): HasMany
    {
        return $this->hasMany(DisputeProposal::class)->orderByDesc('created_at');
    }

    /** @return HasOne<DisputeProposal, $this> */
    public function latestProposal(): HasOne
    {
        return $this->hasOne(DisputeProposal::class)->latestOfMany();
    }

    /** @return MorphMany<Media, $this> */
    public function evidence(): MorphMany
    {
        return $this->morphMany(Media::class, 'attachable')->where('collection', 'evidence')->orderBy('position');
    }

    public function money(?int $amount): ?Money
    {
        return Money::nullable($amount, $this->currency);
    }

    public function isParty(User $user): bool
    {
        return $user->id === $this->buyer_id || $user->id === $this->seller_id;
    }
}
